function getGenshinArtifactSet(id) {
    return GENSHIN_ARTIFACT_DB.find((a) => String(a.id) === String(id)) || null;
}

function searchGenshinArtifactSets(query) {
    if (!query) return GENSHIN_ARTIFACT_DB.slice(0, 10);
    const lowerQuery = query.toLowerCase();
    return GENSHIN_ARTIFACT_DB.filter((a) => a.name.toLowerCase().includes(lowerQuery));
}
